def p_all_red(red, blue, draws):
    p = 1.0
    for i in range(draws):
        p *= red / (red + blue)
    return p

def post(prior, sens=0.95, spec=0.95):
    tp = prior * sens
    fp = (1 - prior) * (1 - spec)
    return tp / (tp + fp)

for prior in [0.5, 0.1, 0.01, 0.001]:
    print(prior, round(post(prior), 3))

def update(prior, sens=0.9, spec=0.91):
    tp = prior * sens
    fp = (1 - prior) * (1 - spec)
    return tp / (tp + fp)

p = 0.01
for test in range(1, 4):
    p = update(p)
    print(test, round(p, 3))

